namespace sv_0b0c5ddfd88448b7978c10aee04090ac.Services;

/// <summary>
/// Scoped service (per-circuit in Blazor Server) that holds the current warehouse
/// selection and notifies all subscribed components when it changes.
/// Each user circuit gets its own instance, ensuring independent state.
/// </summary>
public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Action? OnChange;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } = new List<(string, string)>
    {
        ("WH-001", "Warehouse A - Downtown"),
        ("WH-002", "Warehouse B - Airport"),
        ("WH-003", "Warehouse C - Harbor"),
        ("WH-004", "Warehouse D - Industrial Park")
    };

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_0b0c5ddfd88448b7978c10aee04090ac.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and coordinates polling
/// notifications across all subscribed components in the same circuit.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private Timer? _pollingTimer;
    private int _currentAlertCount;
    private string? _pollingWarehouseId;
    private int _subscriberCount;

    public int CurrentAlertCount => _currentAlertCount;

    /// <summary>
    /// Fired when new alert data arrives. All subscribed components receive this,
    /// not just the one that triggered polling.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query for items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Starts polling for the given warehouse. Multiple subscribers share one timer.
    /// </summary>
    public void StartPolling(string warehouseId)
    {
        _subscriberCount++;

        if (_pollingTimer is not null && _pollingWarehouseId == warehouseId)
            return;

        StopTimer();
        _pollingWarehouseId = warehouseId;
        _pollingTimer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
    }

    /// <summary>
    /// Decrements subscriber count. Stops polling when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            StopTimer();
        }
    }

    /// <summary>
    /// Restarts polling for a new warehouse (e.g., when user switches selection).
    /// </summary>
    public void ChangeWarehouse(string warehouseId)
    {
        if (_pollingWarehouseId == warehouseId) return;
        _pollingWarehouseId = warehouseId;

        if (_subscriberCount > 0)
        {
            StopTimer();
            _pollingTimer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
        }
    }

    private async void PollCallback(object? state)
    {
        if (_pollingWarehouseId is null) return;

        _currentAlertCount = await GetLowStockCountAsync(_pollingWarehouseId);

        if (OnAlertCountChanged is not null)
        {
            await OnAlertCountChanged.Invoke();
        }
    }

    private void StopTimer()
    {
        _pollingTimer?.Dispose();
        _pollingTimer = null;
    }

    public void Dispose()
    {
        StopTimer();
    }
}

