@page "/dashboard"
@rendermode InteractiveServer
@using sv_0b0c5ddfd88448b7978c10aee04090ac.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <h5 class="mb-0">Current Warehouse: @GetWarehouseName()</h5>
    </div>
    <div class="card-body">
        <div class="row">
            <div class="col-md-4">
                <div class="card text-bg-@(_alertCount > 5 ? "danger" : _alertCount > 0 ? "warning" : "success")">
                    <div class="card-body text-center">
                        <h2>@_alertCount</h2>
                        <p class="mb-0">Low-Stock Alerts</p>
                    </div>
                </div>
            </div>
            <div class="col-md-8">
                <p class="text-muted">
                    Polling every 10 seconds for items below minimum stock levels.
                </p>
                <p>
                    <strong>Warehouse ID:</strong> @WarehouseState.CurrentWarehouseId<br />
                    <strong>Last Updated:</strong> @_lastUpdated.ToString("HH:mm:ss")<br />
                    <strong>Status:</strong>
                    @if (_alertCount > 5)
                    {
                        <span class="text-danger fw-bold">Critical — Restock Immediately</span>
                    }
                    else if (_alertCount > 0)
                    {
                        <span class="text-warning fw-bold">Attention Needed</span>
                    }
                    else
                    {
                        <span class="text-success fw-bold">All Clear</span>
                    }
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private int _alertCount;
    private DateTime _lastUpdated = DateTime.Now;

    protected override void OnInitialized()
    {
        // Subscribe to notifications from both services
        AlertService.OnAlertCountChanged += OnAlertDataArrived;
        WarehouseState.OnChange += OnWarehouseChanged;

        // Start polling for the current warehouse
        AlertService.StartPolling(WarehouseState.CurrentWarehouseId);
    }

    private async Task OnAlertDataArrived()
    {
        _alertCount = AlertService.CurrentAlertCount;
        _lastUpdated = DateTime.Now;
        await InvokeAsync(StateHasChanged);
    }

    private void OnWarehouseChanged()
    {
        AlertService.ChangeWarehouse(WarehouseState.CurrentWarehouseId);
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= OnAlertDataArrived;
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.StopPolling();
    }

    private string GetWarehouseName()
    {
        return WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
            ?? WarehouseState.CurrentWarehouseId;
    }
}

